<script>
  let currentRole = 'ciudadano';

  function setRole(role) {
    currentRole = role;
    const tabCiudadano = document.getElementById('tab-ciudadano');
    const tabMedico = document.getElementById('tab-medico');
    const fieldsCiudadano = document.getElementById('fields-ciudadano');
    const fieldsMedico = document.getElementById('fields-medico');
    const infoCiudadano = document.getElementById('info-ciudadano');
    const infoMedico = document.getElementById('info-medico');
    const btnSubmitLabel = document.getElementById('btn-submit-label');

    if (role === 'ciudadano') {
      // Activar Tab Ciudadano
      tabCiudadano.classList.add('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
      tabCiudadano.classList.remove('text-on-surface-variant');
      tabMedico.classList.remove('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
      tabMedico.classList.add('text-on-surface-variant');

      // Mostrar Formularios & Datos
      fieldsCiudadano.classList.remove('hidden');
      fieldsMedico.classList.add('hidden');
      infoCiudadano.classList.remove('hidden');
      infoMedico.classList.add('hidden');
      btnSubmitLabel.textContent = 'Crear cuenta ciudadana y acceder';

      // Requerimientos
      document.getElementById('c-nombre').required = true;
      document.getElementById('c-numero-doc').required = true;
      document.getElementById('c-telefono').required = true;
      document.getElementById('c-vereda').required = true;
      document.getElementById('c-pin').required = true;

      document.getElementById('m-nombre').required = false;
      document.getElementById('m-rethus').required = false;
      document.getElementById('m-email').required = false;
      document.getElementById('m-password').required = false;
    } else {
      // Activar Tab Médico
      tabMedico.classList.add('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
      tabMedico.classList.remove('text-on-surface-variant');
      tabCiudadano.classList.remove('bg-surface-container-lowest', 'text-primary', 'shadow-sm');
      tabCiudadano.classList.add('text-on-surface-variant');

      // Mostrar Formularios & Datos
      fieldsCiudadano.classList.add('hidden');
      fieldsMedico.classList.remove('hidden');
      infoCiudadano.classList.add('hidden');
      infoMedico.classList.remove('hidden');
      btnSubmitLabel.textContent = 'Crear credencial médica institucional';

      // Requerimientos
      document.getElementById('c-nombre').required = false;
      document.getElementById('c-numero-doc').required = false;
      document.getElementById('c-telefono').required = false;
      document.getElementById('c-vereda').required = false;
      document.getElementById('c-pin').required = false;

      document.getElementById('m-nombre').required = true;
      document.getElementById('m-rethus').required = true;
      document.getElementById('m-email').required = true;
      document.getElementById('m-password').required = true;
    }
  }

  function handleRegistration() {
    const toast = document.getElementById('toast-success');
    const toastMsg = document.getElementById('toast-message');
    
    if (currentRole === 'ciudadano') {
      const nombre = document.getElementById('c-nombre').value || 'Campesino(a)';
      toastMsg.textContent = `Bienvenido(a), ${nombre}. Se vinculó tu ficha veredal para recibir confirmación de patrulla por SMS.`;
    } else {
      const nombre = document.getElementById('m-nombre').value || 'Profesional';
      toastMsg.textContent = `Credencial emitida para ${nombre}. Datos habilitados para georreferenciación y descenso veredal.`;
    }

    toast.classList.remove('translate-y-32', 'opacity-0');
    toast.classList.add('translate-y-0', 'opacity-100');

    setTimeout(() => {
      toast.classList.add('translate-y-32', 'opacity-0');
      toast.classList.remove('translate-y-0', 'opacity-100');
    }, 4500);
  }
</script></main></body></html>